<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,Link,router}from'@inertiajs/vue3';import{reactive}from'vue';const props=defineProps<{reports:any,filters:any}>();const form=reactive({status:props.filters.status||''});const filter=()=>router.get(route('admin.reports.index'),form,{preserveState:true});</script>
<template><Head title="Reports"/><AdminLayout><h1 class="text-2xl font-bold">Message reports</h1><form class="mt-5" @submit.prevent="filter"><select v-model="form.status" class="rounded border px-3 py-2"><option value="">All statuses</option><option>pending</option><option>dismissed</option><option>actioned</option></select><button class="ml-2 rounded bg-slate-900 px-4 py-2 text-white">Filter</button></form><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-500"><tr><th class="p-4">Reporter</th><th>Reported user</th><th>Reason</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="report in reports.data" :key="report.id" class="border-t"><td class="p-4">{{report.reporter?.name}}</td><td>{{report.message?.sender?.name}}</td><td class="capitalize">{{report.reason}}</td><td>{{new Date(report.created_at).toLocaleString()}}</td><td class="capitalize">{{report.status}}</td><td><Link :href="route('admin.reports.show',report.id)" class="text-cyan-700">Review</Link></td></tr><tr v-if="!reports.data.length"><td colspan="6" class="p-8 text-center text-slate-500">No reports found.</td></tr></tbody></table></div></AdminLayout></template>
